mapper.select:
SELECT id, order_no, user_id, seckill_id, product_id, seckill_price, quantity, total_amount, status, shipping_company, shipping_no, ship_time, confirm_time, pay_time, pay_expire_time, transaction_id, pay_method, cancel_time, cancel_reason, is_deleted, create_time, update_time FROM t_seckill_order WHERE is_deleted = 0
AND user_id = #{userId}
AND seckill_id = #{seckillId}
AND status = #{status}
ORDER BY create_time DESC

SELECT DATE(create_time) AS dt, COUNT(*) AS cnt, IFNULL(SUM(total_amount), 0) AS amt FROM t_seckill_order WHERE is_deleted = 0 AND status IN
#{s}
AND create_time >= #{startDate} AND create_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY) GROUP BY DATE(create_time)

SELECT status AS status, COUNT(*) AS cnt FROM t_seckill_order WHERE is_deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY status

SELECT * FROM ( /* ====== 秒杀订单 ====== */ SELECT o.id, 'SECKILL' AS order_type, o.order_no, o.user_id, u.username, o.seckill_id, p.name AS seckill_name, o.product_id, p.name AS product_name, o.seckill_price, o.quantity, o.total_amount, o.status, o.shipping_company, o.shipping_no, o.ship_time, o.confirm_time, o.pay_time, o.pay_expire_time, o.transaction_id, o.pay_method, o.cancel_time, o.cancel_reason, o.create_time, o.update_time FROM t_seckill_order o INNER JOIN t_user u ON u.id = o.user_id AND u.is_deleted = 0 INNER JOIN t_product p ON p.id = o.product_id AND p.is_deleted = 0 WHERE o.is_deleted = 0
UNION ALL
/* ====== 普通订单 ====== */ SELECT o.id, 'NORMAL' AS order_type, o.order_no, o.user_id, u.username, NULL AS seckill_id, NULL AS seckill_name, NULL AS product_id, (SELECT noi.product_name FROM t_normal_order_item noi WHERE noi.order_id = o.id AND noi.is_deleted = 0 ORDER BY noi.id LIMIT 1) AS product_name, NULL AS seckill_price, (SELECT IFNULL(SUM(noi.quantity), 0) FROM t_normal_order_item noi WHERE noi.order_id = o.id AND noi.is_deleted = 0) AS quantity, o.total_amount, o.status, o.shipping_company, o.shipping_no, o.ship_time, o.confirm_time, o.pay_time, o.pay_expire_time, o.transaction_id, o.pay_method, o.cancel_time, o.cancel_reason, o.create_time, o.update_time FROM t_normal_order o INNER JOIN t_user u ON u.id = o.user_id AND u.is_deleted = 0 WHERE o.is_deleted = 0 ) t
AND t.order_type = #{req.orderType}
AND t.order_no LIKE CONCAT('%', #{req.orderNo}, '%')
AND t.create_time >= #{req.startLdt} AND t.create_time < #{req.endLdt}
AND t.status = #{req.status}
AND t.user_id = #{req.userId}
AND t.product_id = #{req.productId}
AND t.seckill_id = #{req.seckillId}
AND t.create_time >= #{req.startLdt}
AND t.create_time <= #{req.endLdt}
AND t.pay_time >= #{req.payStartLdt}
AND t.pay_time <= #{req.payEndLdt}
AND t.total_amount >= #{req.minAmount}
AND t.total_amount <= #{req.maxAmount}
ORDER BY
t.create_time t.pay_time t.total_amount t.order_no t.create_time
ASC DESC

SELECT o.seckill_id AS seckillId, p.name AS productName, sg.seckill_price AS seckillPrice, COUNT(o.id) AS salesCount, IFNULL(SUM(o.total_amount), 0) AS totalAmount FROM t_seckill_order o LEFT JOIN t_seckill_goods sg ON sg.id = o.seckill_id AND sg.is_deleted = 0 LEFT JOIN t_product p ON p.id = o.product_id AND p.is_deleted = 0 WHERE o.is_deleted = 0 AND o.status IN
#{s}
GROUP BY o.seckill_id, p.name, sg.seckill_price ORDER BY totalAmount DESC, salesCount DESC LIMIT #{limit}
